{
  "synthesis": "Extracted facts are gated by memory_fact_gate before being committed as semantic edges.",
  "topic": {
    "id": "ent_tiera",
    "name": "Tier-A curator extraction",
    "sources": [
      {
        "id": "f1",
        "kind": "doc_summary",
        "payload": {
          "summary": "Tier-A covers the mechanical curator stages: extract_docs, extract_code, index_narrative, index_claims, index_code_unit",
          "source_file": "docs/curator.md",
          "status": "accepted",
          "priority": "high",
          "components": [
            "curator"
          ]
        }
      },
      {
        "id": "f2",
        "kind": "claim",
        "payload": {
          "subject": "Tier-A",
          "attribute": "thinking",
          "value": "disabled",
          "claim_kind": "behavior",
          "text": "Tier-A sets disable_thinking on the provider."
        }
      },
      {
        "id": "f3",
        "kind": "claim",
        "payload": {
          "subject": "memory_facts",
          "attribute": "volume",
          "value": "one call per note",
